ALTER TABLE public.league_roles ADD COLUMN is_co_commissioner boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.league_commissioner(lid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.league_roles r JOIN public.leagues l ON l.id=r.league_id WHERE r.league_id=lid AND r.user_id=auth.uid() AND NOT l.is_demo AND (l.owner_id=auth.uid() OR r.role='commissioner' OR r.is_co_commissioner)) $$;
CREATE POLICY creator_read_league_roles ON public.league_roles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.leagues l WHERE l.id=league_roles.league_id AND l.owner_id=auth.uid() AND NOT l.is_demo));
CREATE FUNCTION public.set_league_co_commissioner(lid uuid, member_id uuid, promoted boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE creator uuid; demo boolean; BEGIN SELECT owner_id,is_demo INTO creator,demo FROM public.leagues WHERE id=lid FOR UPDATE; IF auth.uid() IS NULL OR creator IS DISTINCT FROM auth.uid() OR demo THEN RAISE EXCEPTION 'Only the league creator can appoint co-commissioners'; END IF; IF member_id=creator THEN RAISE EXCEPTION 'The league creator remains commissioner'; END IF; IF NOT EXISTS(SELECT 1 FROM public.teams WHERE league_id=lid AND owner_id=member_id) OR NOT EXISTS(SELECT 1 FROM public.league_roles WHERE league_id=lid AND user_id=member_id) THEN RAISE EXCEPTION 'Choose a signed-in member of this league'; END IF; UPDATE public.league_roles SET is_co_commissioner=promoted WHERE league_id=lid AND user_id=member_id; INSERT INTO public.league_activity(league_id,message) SELECT lid, name || CASE WHEN promoted THEN ' was appointed co-commissioner.' ELSE ' returned to league member.' END FROM public.teams WHERE league_id=lid AND owner_id=member_id; END $$;
REVOKE ALL ON FUNCTION public.set_league_co_commissioner(uuid,uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_league_co_commissioner(uuid,uuid,boolean) TO authenticated;
COMMENT ON COLUMN public.league_roles.is_co_commissioner IS 'Creator-managed delegated league tools access. Direct member updates remain denied by RLS.';